  "swift-public-types":
    '  /// A fully resolved prompt ready to be sent to an LLM.\n  ///\n  /// The `Output` type parameter is the parsed response type for the template.\n  /// The `ToolExecutor` type parameter is the object whose methods implement the\n  /// template\'s tools, or `NoTools` when no tools are available.\n  ///\n  /// Build and send the API request using `systemMessage`, `userMessage`,\n  /// `examples`, and `tools`. If the model requests tool calls, dispatch\n  /// them with `executeTools` and then parse the final response with `parseResponse`.\n  public struct Prompt<Output, ToolExecutor: Sendable>: Sendable {\n    /// Metadata for this prompt.\n    public let meta: Meta\n    public let systemMessage: String\n    public let userMessage: String\n    /// Few-shot examples.\n    public let examples: [FewShotExample]\n    /// The tools which can be called by the LLM, keyed by tool name.\n    public let tools: [String: Tool]\n    public let outputFormat: OutputFormat\n    public let templateId: TemplateId\n    private let fromJson: @Sendable (Data) throws -> Output\n\n    public init(\n      meta: Meta,\n      systemMessage: String,\n      userMessage: String,\n      examples: [FewShotExample],\n      tools: [String: Tool],\n      outputFormat: OutputFormat,\n      templateId: TemplateId,\n      fromJson: @escaping @Sendable (Data) throws -> Output\n    ) {\n      self.meta = meta\n      self.systemMessage = systemMessage\n      self.userMessage = userMessage\n      self.examples = examples\n      self.tools = tools\n      self.outputFormat = outputFormat\n      self.templateId = templateId\n      self.fromJson = fromJson\n    }\n\n    /// Parse an LLM response into the expected output type.\n    public func parseResponse(_ response: String) throws -> Output {\n      return try doParseResponse(\n        response,\n        outputFormat: outputFormat,\n        templateId: templateId,\n        fromJson: fromJson\n      )\n    }\n\n    /// Execute the given tool calls in parallel.\n    public func executeTools(\n      _ toolCalls: [ToolCall],\n      toolExecutor: ToolExecutor\n    ) async throws -> [ToolCallResponse] {\n      let namespace = templateId.description.split(separator: ":").first.map(String.init) ?? ""\n      return try await withThrowingTaskGroup(of: (Int, ToolCallResponse).self) { group in\n        for (index, call) in toolCalls.enumerated() {\n          group.addTask {\n            let result = try await executeToolCall(\n              toolCall: call,\n              namespace: namespace,\n              executor: toolExecutor\n            )\n            return (index, result)\n          }\n        }\n        var results = [(Int, ToolCallResponse)]()\n        for try await item in group {\n          results.append(item)\n        }\n        return results.sorted(by: { $0.0 < $1.0 }).map { $0.1 }\n      }\n    }\n  }\n\n  /// The expected format of the model output.\n  public enum OutputFormat: Sendable, Equatable {\n    case json(JsonOutputFormat)\n    case text(TextOutputFormat)\n\n    /// Whether this format is JSON.\n    public var isJson: Bool {\n      if case .json = self { return true }\n      return false\n    }\n\n    /// Whether this format is free-form text.\n    public var isText: Bool {\n      if case .text = self { return true }\n      return false\n    }\n\n    /// Free-form text output format specification.\n    public static var text: OutputFormat {\n      .text(TextOutputFormat())\n    }\n\n    public static func == (lhs: OutputFormat, rhs: OutputFormat) -> Bool {\n      switch (lhs, rhs) {\n      case (.json(let l), .json(let r)):\n        return l.stringifiedJsonSchema == r.stringifiedJsonSchema\n      case (.text, .text):\n        return true\n      default:\n        return false\n      }\n    }\n  }\n\n  /// JSON output format specification.\n  public struct JsonOutputFormat: Sendable, Equatable {\n    /// The JSON schema against which model outputs are validated.\n    public let stringifiedJsonSchema: String\n\n    fileprivate init(\n      stringifiedJsonSchema: String\n    ) {\n      self.stringifiedJsonSchema = stringifiedJsonSchema\n    }\n  }\n\n  /// Free-form text output format specification.\n  public struct TextOutputFormat: Sendable, Equatable {\n    fileprivate init() {}\n  }\n\n  /// A tool definition exposed to an LLM.\n  public struct Tool: Sendable, Codable, Equatable {\n    /// The name of the tool.\n    public let name: String\n    /// Description of the tool\'s capabilities.\n    public let description: String\n\n    public init(name: String, description: String) {\n      self.name = name\n      self.description = description\n    }\n  }\n\n  /// A single few-shot example consisting of a user message, optional intermediate\n  /// tool-call steps, and the expected response.\n  public struct FewShotExample: Sendable, Codable, Equatable {\n    /// The user message for this example.\n    public let userMessage: String\n    /// Intermediate tool call steps, if any.\n    public let intermediateSteps: [IntermediateStepExample]\n    /// The expected assistant response.\n    public let response: String\n\n    public init(\n      userMessage: String,\n      intermediateSteps: [IntermediateStepExample],\n      response: String,\n    ) {\n      self.userMessage = userMessage\n      self.intermediateSteps = intermediateSteps\n      self.response = response\n    }\n  }\n\n  /// One intermediate step within a few-shot example, containing the tool\n  /// calls made at that step.\n  public struct IntermediateStepExample: Sendable, Codable, Equatable {\n    /// Tool calls made in parallel at this step.\n    public let toolCalls: [ToolCallExample]\n\n    public init(toolCalls: [ToolCallExample]) {\n      self.toolCalls = toolCalls\n    }\n  }\n\n  /// A single tool call recorded inside an intermediate step.\n  public struct ToolCallExample: Sendable, Codable, Equatable {\n    /// Identifier for the tool call.\n    public let callId: String\n    /// The name of the tool that was called.\n    public let toolName: String\n    /// The stringified JSON input passed to the tool.\n    public let stringifiedInput: String\n    /// The stringified JSON output returned by the tool.\n    public let stringifiedOutput: String\n\n    public init(\n      callId: String,\n      toolName: String,\n      stringifiedInput: String,\n      stringifiedOutput: String,\n    ) {\n      self.callId = callId\n      self.toolName = toolName\n      self.stringifiedInput = stringifiedInput\n      self.stringifiedOutput = stringifiedOutput\n    }\n  }\n\n  /// A tool call invocation requested by an LLM.\n  public struct ToolCall: Sendable, Codable, Equatable {\n    /// Identifier for the tool call.\n    public let callId: String\n    /// The name of the tool to execute.\n    public let toolName: String\n    /// The stringified JSON input arguments.\n    public let stringifiedInput: String\n\n    public init(callId: String, toolName: String, stringifiedInput: String) {\n      self.callId = callId\n      self.toolName = toolName\n      self.stringifiedInput = stringifiedInput\n    }\n  }\n\n  /// The result of executing a tool call.\n  public struct ToolCallResponse: Sendable, Codable, Equatable {\n    /// Identifier matching the original tool call.\n    public let callId: String\n    /// The stringified JSON output from executing the tool.\n    public let stringifiedOutput: String\n\n    public init(callId: String, stringifiedOutput: String) {\n      self.callId = callId\n      self.stringifiedOutput = stringifiedOutput\n    }\n  }\n\n  /// Used as the `ToolExecutor` type parameter when a prompt has no tools.\n  public struct NoTools: Sendable, Equatable {\n    /// Shared singleton instance.\n    public static let shared = NoTools()\n    private init() {}\n  }\n\n  /// Default instance of NoTools for prompts without tools.\n  public static let noTools = NoTools.shared',
